using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // HasIndex removed — Cosmos DB indexing is managed via the container's
        // indexing policy (Azure Portal / Bicep / Terraform), not EF Core.
        // EF Core 9 throws InvalidOperationException if HasIndex is called.

        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the default discriminator property from
            // "Discriminator" to "$type". Our 500K existing documents and
            // direct SQL queries use the old name — keep it.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the id format from "Product|123" to "123".
            // Existing documents use the compound format — preserve it so
            // FindAsync and point-reads continue to work.
            entity.HasRootDiscriminatorInJsonId(true);
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

