using System.Linq;
using System.Threading.Tasks;

class CosmosQuery
{
    async Task FindProductsAsync(ProductContext ctx)
    {
        // Direct Cosmos SQL — the discriminator property is still "Discriminator"
        // because we configured HasDiscriminator<string>("Discriminator") to stay
        // compatible with existing documents. Without that override, EF Core 9
        // would default to "$type" and this query would return zero results.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 Cosmos provider no longer supports synchronous I/O.
        // ToList() → ToListAsync(), SaveChanges() → SaveChangesAsync(), etc.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

